export const logPageView = async (path: string) => {
  console.log(`[Analytics] Logging page view for: ${path}`);
  // Simulate network delay
  await new Promise((resolve) => setTimeout(resolve, 500));
  console.log(`[Analytics] Successfully logged page view for: ${path}`);
};

import { after } from 'next/server';
import { logPageView } from '../utils/analytics';

export default function WelcomeTracker() {
  after(async () => {
    await logPageView('/welcome');
  });

  return (
    <div className="p-4 border rounded shadow-sm bg-gray-50">
      <h2 className="text-xl font-bold mb-2">Welcome to our site!</h2>
      <p className="text-gray-600">We are happy to have you here.</p>
    </div>
  );
}

